package com.playsphere.chat;import com.playsphere.common.Ids;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="chat_messages") public class ChatMessage{@Id @Column(length=36)private String id;@Column(name="conversation_id",nullable=false,length=36)private String conversationId;@Column(name="sender_user_id",nullable=false,length=36)private String senderUserId;@Column(nullable=false,length=1200)private String body;@Column(name="created_at",nullable=false)private Instant createdAt;protected ChatMessage(){}public ChatMessage(String c,String s,String b){id=Ids.uuid();conversationId=c;senderUserId=s;body=b;createdAt=Instant.now();}public String getId(){return id;}public String getConversationId(){return conversationId;}public String getSenderUserId(){return senderUserId;}public String getBody(){return body;}public Instant getCreatedAt(){return createdAt;}}
